  proud: { rows: ['..y..', 'yyayy', '.yay.', 'yy.yy', 'y...y'], palette: { y: P.amber, a: P.yellow } },
  love: { rows: ['.r.r.', 'rhrrr', 'rrrrd', '.rrd.', '..d..'], palette: { r: P.red, h: P.coral, d: P.blood } },
  sad: { rows: ['.ggg.', 'ggggg', '.....', 'b.b.b', '.b.b.'], palette: { g: P.steel, b: P.sky } },
