  confused: { rows: ['.kkk.', 'k...k', '...k.', '.....', '..k..'], palette: { k: P.navy } },
  sleepy: { rows: ['kkkkk', '...k.', '..k..', '.k...', 'kkkkk'], palette: { k: P.slate } },
