// Speech and thought bubbles, and the "needs you" call: the words wrapped to fit, the bubble set
// beside Claude on whichever side covers the least of the sign boards, a tail toward him.

import type { Canvas } from './canvas'
import { cellWidth } from './canvas'
import { CALL, CLAUDE_WIDTH, SPEECH, THOUGHT } from './sprites'
import { clamp } from './util'

/** A block of cells. */
export type Rect = { left: number; top: number; width: number; height: number }

export type BubbleKind = 'say' | 'think' | 'call'
export type Bubble = Rect & {
  kind: BubbleKind
  lines: string[]
  /** The row its tail joins Claude on. */
  link: number
  side: 'right' | 'left' | 'above'
}

/** How many cells two blocks share. */
export function overlap(a: Rect, b: Rect): number {
  const w = Math.min(a.left + a.width, b.left + b.width) - Math.max(a.left, b.left)
  const h = Math.min(a.top + a.height, b.top + b.height) - Math.max(a.top, b.top)
  return w > 0 && h > 0 ? w * h : 0
}

/** The cells a bubble covers, its tail to Claude included. */
export function bubbleRect(b: Bubble): Rect {
  return { left: b.left - 2, top: b.top, width: b.width + 4, height: b.height }
}

/** Words wrapped to lines of at most `width` cells; a word longer than a line is cut short. */
export function wrap(text: string, width: number): string[] {
  const lines: string[] = []
  let line = ''
  for (const word of text.split(/\s+/).filter(Boolean)) {
    const w = cellWidth(word) > width ? [...word].slice(0, width - 1).join('') + '…' : word
    if (!line) line = w
    else if (cellWidth(line) + 1 + cellWidth(w) <= width) line += ' ' + w
    else {
      lines.push(line)
      line = w
    }
  }
  if (line) lines.push(line)
  return lines.length ? lines : ['']
}

/**
 * Lays a bubble out beside Claude, his left column at `x` and his head on `headRow`: the narrowest
 * bubble that holds the whole remark (else the widest, ellipsized), on the side that covers the
 * least of `avoid`; above him when neither side has room.
 */
export function layoutBubble(
  text: string,
  kind: BubbleKind,
  at: { x: number; headRow: number; columns: number; rows: number },
  avoid: readonly Rect[],
): Bubble {
  const { headRow, columns, rows } = at
  const maxInner = clamp(columns - CLAUDE_WIDTH - 8, 10, 40)
  const maxLines = clamp(rows - 3, 1, 4)
  let inner = Math.min(maxInner, 26)
  let lines = wrap(text, inner)
  while (lines.length > maxLines && inner < maxInner) {
    inner = Math.min(maxInner, inner + 4)
    lines = wrap(text, inner)
  }
  if (lines.length > maxLines) {
    lines = lines.slice(0, maxLines)
    const last = lines[maxLines - 1]!
    lines[maxLines - 1] = (cellWidth(last) >= inner ? [...last].slice(0, inner - 1).join('') : last) + '…'
  }
  const width = Math.max(...lines.map(cellWidth)) + 4
  const height = lines.length + 2
  const top = clamp(headRow - height + 3, 0, Math.max(0, rows - height))
  const link = clamp(headRow + 1, top + 1, top + height - 2)
  const x = Math.round(at.x)

  const sides: Bubble[] = []
  if (x + CLAUDE_WIDTH + 2 + width <= columns) sides.push({ kind, lines, width, height, top, link, side: 'right', left: x + CLAUDE_WIDTH + 2 })
  if (x - 2 - width >= 0) sides.push({ kind, lines, width, height, top, link, side: 'left', left: x - 2 - width })
  if (!sides.length) sides.push({ kind, lines, width, height, top: 0, link, side: 'above', left: clamp(x - Math.floor(width / 2), 0, Math.max(0, columns - width)) })
  const cost = (b: Bubble) => avoid.reduce((sum, r) => sum + overlap(bubbleRect(b), r), 0)
  return sides.reduce((best, b) => (cost(b) < cost(best) ? b : best))
}

export function drawBubble(c: Canvas, b: Bubble) {
  const style = b.kind === 'say' ? SPEECH : b.kind === 'call' ? CALL : THOUGHT
  c.box(b.left, b.top, b.lines, style.fg, style.bg, style.border)
  // a speech tail is a line to him; a thought's is a little circle
  if (b.side === 'right') {
    if (b.kind !== 'think') {
      c.text(b.left, b.link, '┤', style.border, style.bg)
      c.text(b.left - 2, b.link, '──', style.border)
    } else c.text(b.left - 1, b.link, 'o', style.border)
  } else if (b.side === 'left') {
    if (b.kind !== 'think') {
      c.text(b.left + b.width - 1, b.link, '├', style.border, style.bg)
      c.text(b.left + b.width, b.link, '──', style.border)
    } else c.text(b.left + b.width, b.link, 'o', style.border)
  }
}

files.hooks/effects.ts:
// What the figure gives off, each a short animation from `start` to `until`: sparkles, puffs of
// smoke, hearts, tears, steam, sweat, z's, dust and a balloon let go. And particles (dirt from a
// shovel, drops from a watering can) that fly in an arc under a little gravity.

import type { Canvas } from './canvas'
import { BALLOON_UP, BITS, P } from './sprites'

export type Effect =
  | { kind: 'sparkle'; x: number; y: number; color: number; start: number; until: number }
  | { kind: 'poof' | 'heart' | 'tear' | 'steam' | 'sweat' | 'zzz' | 'dust' | 'balloon'; x: number; y: number; start: number; until: number }
export type EffectKind = Effect['kind']

export type Particle = { x: number; y: number; vx: number; vy: number; until: number; color: number }

/** The particles still in the air at `now`, each moved on by `dt` seconds. */
export function fly(particles: readonly Particle[], now: number, dt: number): Particle[] {
  const flying = particles.filter(p => p.until > now)
  for (const p of flying) {
    p.x += p.vx * dt
    p.y += p.vy * dt
    p.vy += 40 * dt
  }
  return flying
}

/** A particle is a 2-pixel clump. */
export function drawParticle(c: Canvas, p: Particle) {
  c.set(p.x, p.y, p.color)
  c.set(p.x + 1, p.y, p.color)
}

export function drawEffect(c: Canvas, e: Effect, now: number) {
  const t = (now - e.start) / (e.until - e.start)
  switch (e.kind) {
    case 'sparkle':
      // a dot that opens into a plus and closes again
      c.set(e.x, e.y, P.white)
      if (t >= 0.33 && t <= 0.8) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) c.set(e.x + dx, e.y + dy, e.color)
      return
    case 'poof': {
      // eight 2-pixel clumps flying out, white turning grey
      const r = 1.5 + t * 5
      const color = t < 0.5 ? P.white : P.mist
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2
        const px = e.x + Math.cos(a) * r * 1.6
        const py = e.y + Math.sin(a) * r * 0.8
        c.set(px, py, color)
        c.set(px + 1, py, color)
      }
      return
    }
    case 'heart': {
      // floats up with a slight sway, the last stretch shrunk to a dot
      const x = e.x + Math.round(Math.sin(t * 6))
      const y = e.y - Math.round(t * 6)
      if (t < 0.8) c.sprite(x, y, BITS.heart.rows, BITS.heart.palette)
      else c.set(x + 2, y + 1, P.coral)
      return
    }
    case 'tear':
      // a drop running down from the eye: a light head over a darker tail
      c.set(e.x, e.y + t * 5, P.sky)
      c.set(e.x, e.y + t * 5 - 1, P.navy)
      return
    case 'steam': {
      const y = e.y - t * 4
      const color = t < 0.5 ? P.silver : P.steel
      c.set(e.x, y, color)
      c.set(e.x + 1, y - 1, color)
      return
    }
    case 'sweat': {
      const y = e.y + t * 3
      c.set(e.x, y, P.white)
      c.set(e.x, y + 1, P.sky)
      return
    }
    case 'zzz': {
      // a z drifting up and right, growing into a Z
      const col = e.x + Math.round(t * 4)
      const row = Math.floor((e.y - t * 6) / 2)
      if (row >= 0) c.text(col, row, t < 0.5 ? 'z' : 'Z', t < 0.7 ? P.silver : P.steel)
      return
    }
    case 'dust':
      c.set(e.x, e.y - t * 2, t < 0.5 ? P.silver : P.mist)
      c.set(e.x + 1, e.y - t * 2, P.mist)
      return
    case 'balloon': {
      // let go: it drifts up and off the top, swaying
      const y = Math.round(e.y - t * (e.y + 8))
      const x = e.x + Math.round(Math.sin(t * 9) * 1.5)
      c.sprite(x, y, BALLOON_UP.rows, BALLOON_UP.palette)
      return
    }
  }
}

